// Fade to black, close the event's music, clean up...
StartBrightFade(SCREEN_A, -1.0, 30.0);
CMND_MESWIN_UNLOCK();
hEvSnd = CMND_SND_GET_BGM_SNDID();
CMND_SND_CLOSE(hEvSnd, 30);
EndStandEvent();
CamCtrlExit();
// ... and keep the match from fading back in on its own
CMND_BTL_NO_FADEIN();
EndScEvent(isEvUpperDisp, scEvHdl);

StartBrightFade(SCREEN_A, -1.0, 30);
CMND_MESWIN_UNLOCK();
EndStandEvent();
CamCtrlExit();
CMND_BTL_NO_FADEIN(true);
EndScEvent(isEvUpperDisp, scEvHdl);
